// Check which remotes are configured
// Terminal command: git remote -v
// Output shows:
// origin  https://github.com/yourname/spring-boot-app.git (fetch)
// origin  https://github.com/yourname/spring-boot-app.git (push)

// Add a new remote called 'upstream' pointing to the original repository
// Terminal: git remote add upstream https://github.com/company/spring-boot-app.git

// Now check again
// Terminal: git remote -v
// origin    https://github.com/yourname/spring-boot-app.git (fetch)
// origin    https://github.com/yourname/spring-boot-app.git (push)
// upstream  https://github.com/company/spring-boot-app.git (fetch)
// upstream  https://github.com/company/spring-boot-app.git (push)

// Fetch changes from the upstream remote
// Terminal: git fetch upstream

// Push your feature branch to origin
// Terminal: git push origin feature/add-user-authentication

// Create a new feature branch locally
// Terminal: git checkout -b feature/add-payment-service

// Make some commits
// Terminal: git add src/main/java/com/example/PaymentService.java
// Terminal: git commit -m "Add payment service skeleton"

// First push: set up tracking with -u flag
// Terminal: git push -u origin feature/add-payment-service
// Output: Branch 'feature/add-payment-service' set up to track remote branch 'feature/add-payment-service' from 'origin'.

// Now tracking is established. Future pushes are simpler:
// Terminal: git commit -m "Implement payment processing"
// Terminal: git push  // No need to specify origin or branch name

// Check tracking relationship
// Terminal: git branch -vv
// Output shows:
// * feature/add-payment-service  a1b2c3d [origin/feature/add-payment-service] Implement payment processing
//   main                         d4e5f6g [origin/main] Update README

// The [origin/feature/add-payment-service] shows the tracking relationship

// Clone a Spring Boot repository from GitHub
// Terminal: git clone https://github.com/company/ecommerce-api.git
// Output shows:
// Cloning into 'ecommerce-api'...
// Receiving objects: 100% (1523/1523), done.
// Resolving deltas: 100% (847/847), done.

// Git has now done several things automatically:

// 1. Created a new directory called 'ecommerce-api'
// 2. Initialized a Git repository inside it (.git folder)
// 3. Downloaded all commits, branches, and tags
// 4. Added 'origin' as a remote

// Check the remote configuration
// Terminal: cd ecommerce-api
// Terminal: git remote -v
// origin  https://github.com/company/ecommerce-api.git (fetch)
// origin  https://github.com/company/ecommerce-api.git (push)

// 5. Checked out the default branch (main) and set up tracking
// Terminal: git branch -vv
// * main  a1b2c3d [origin/main] Add user authentication

// Now you can immediately push and pull
// Terminal: git pull  // Works because tracking is configured
// Terminal: git push  // Works because origin and tracking are set up
